"""Current-review narrative and provenance; the original rubric remains in analyze.py."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
OWNED = ['folio', 'atelier', 'nocturne', 'tufte', 'zephyr-reading', 'simplex-reading', 'pulse-reading', 'litera-reading', 'darkly-reading']
BASELINES = dict(folio='folio-original', atelier='atelier-original', nocturne='nocturne-original', **{n: n.removesuffix('-reading') for n in OWNED if n.endswith('-reading')})
E = html.escape


def history_table(data):
    before = {t['id']: t for t in json.loads((ROOT / 'previous-scores.json').read_text())}
    november10 = {t['id']: t for t in json.loads((ROOT / 'before-color-repair-scores.json').read_text())}
    current = {t['id']: t for t in data}
    rows = []
    for name in OWNED:
        a, b = before[name], current[name]
        prior = november10[name]
        original = current.get(BASELINES.get(name))
        baseline = f'{original["typography"]} / {original["design"]["total"]}' if original else 'October baseline'
        rows.append(f'<tr><th scope="row"><a href="#theme-{name}">{E(b["name"])}</a></th><td>{baseline}</td><td>{a["typography"]} / {a["design"]["total"]}</td><td>{prior["typography"]} / {prior["design"]["total"]}</td><td><strong>{b["typography"]} / {b["design"]["total"]}</strong></td><td>{b["typography"]-prior["typography"]:+d} / {b["design"]["total"]-prior["design"]["total"]:+d}</td></tr>')
    return '<div class="table-wrap"><table class="rubric"><caption>Typography / design, each out of 100. Original custom / stock scores the starting design. The 16 October column scores the first reading refinement. October → November 10 → November 11 uses the same rubric.</caption><thead><tr><th>Project theme</th><th>Original custom / stock</th><th>16 October</th><th>10 November</th><th>11 November</th><th>Change since 10 November</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div><p class="caption">The original custom snapshots and stock themes are unchanged. Current project themes use the lower of both mode scores; the October Reading themes had only their native mode. Expand a theme to see each current mode. Tufte had no separate original snapshot; its October result is preserved in the archive.</p>'


def current_intro(data):
    return '''<p class="section-intro">Elegant compares themes for SmallDocs, a Python website generator. The themes also support Quarto, another publishing tool. Bootstrap supplies base component styles, and Bootswatch supplies named variations. Typography and visual design receive separate scores out of 100.</p><p>We maintain Folio, Atelier, Nocturne and Tufte, plus five Reading adaptations of stock Bootswatch themes. The Reading adaptations are Zephyr Reading, Simplex Reading, Pulse Reading, Litera Reading and Darkly Reading. Refined means the updated custom design, and Original means its preserved starting design.</p><section id="changes"><h2>Nine updated themes under the same scorecard</h2><p>The 10 November review used the exact nine merged revisions of the shared theme settings, checked in their source repositories on 9 November. The 11 November follow-up repaired component and syntax colors in Pulse Reading, Litera Reading and Darkly Reading. Their typography, spacing and shape are unchanged.</p><p>We maintain these nine project themes. All nine define light/dark palettes and named settings for type, space, shape and component states. Component states include disabled buttons and selected navigation. These settings assign colors to their uses, such as body text or selected navigation. Separate profiles assign sizes for documents and presentations. </p><p>The gallery exercises the document profiles. The 25 stock Bootswatches, native Bootstrap, and three original custom snapshots remain unchanged.</p>'''+history_table(data)+'''<div class="callout"><p><strong>The lower typography scores reflect a tradeoff in the rubric.</strong> The themes use 1.60 leading, which means a line height 1.60 times the text size. The unchanged Butterick bands award that 12/20, compared with 20/20 at 1.20 to 1.45. Larger 18 to 20px prose, 16px code, and explicit controls can improve practical use while aligning less closely with this prescriptive scorecard. The score measures fit to the rubric; it is not a reader study.</p></div><p class="small">Measure means the width of the reading column.</p><p>Folio uses Source Serif 4 for ordinary headings. Caslon is available for optional display text, such as large titles. Atelier uses 18px DM Sans. Folio, Nocturne, Tufte, and Litera Reading use 20px serif prose, with small strokes at the ends of letters. The other Reading themes use 18px prose.</p><p>All nine use 16px code, 16px interface text, 14px metadata text (such as captions), 36px titles, and a separate optional 48px display role. The presentation profile supplies sizes for slide tools that use the themes. Document navigation keeps the reading profile.</p><p><a href="history/2026-10-16/typography-report.html">Read the unchanged October typography report</a>  /  <a href="history/2026-10-16/visual-design-report.html">October design report</a>  /  <a href="theme-guide.html">Current theme handbook</a>  /  <a href="./?group=comparisons">Compare the actual pages</a></p></section>'''


def foundations_section():
    checks = json.loads((ROOT / 'foundations-checks.json').read_text())
    scores = {r['id']: r for r in json.loads((ROOT / 'scores.json').read_text())}
    total = sum(len(r['sourceChecks']) for r in checks)
    targets = [('pulse-reading', 'dark', 'foundation-secondary', 1.178), ('litera-reading', 'light', 'foundation-selected', 3.712), ('litera-reading', 'dark', 'foundation-selected', 3.712)]
    rows = []
    for name, mode, label, old in targets:
        context = next(r for r in checks if r['id'] == name and r['mode'] == mode)
        ratios = [c['ratio'] for b in context['browser'] for c in b['renderedText'] if c['label'] == label]
        value = min(ratios)
        rows.append(f'<tr><th>{E(name)} / {mode}</th><td>{label.removeprefix("foundation-")}</td><td>{old:.2f}:1</td><td>{value:.2f}:1</td><td><a href="previews/{name}/foundations.html?mode={mode}">Current specimen</a></td></tr>')
    light = next(m for m in scores['darkly-reading']['modes'] if m['mode'] == 'light')
    rows.append(f'<tr><th>darkly-reading / light</th><td>Sampled syntax minimum</td><td>4.34:1</td><td>{light["metrics"]["syntaxContrast"]:.2f}:1</td><td><a href="previews/darkly-reading/code.html?mode=light">Current code</a></td></tr>')
    failures = [(r['id'],r['mode'],b['viewport'],c['label']) for r in checks for b in r['browser'] for c in b['renderedText'] if not c['passes']]
    status = 'All sampled rendered foundation text clears 4.5:1 at both widths.' if not failures else f'{len(failures)} sampled foundation contexts still need repair; see raw checks.'
    return f'''<section id="foundations"><h2>Foundations and rendered controls</h2><p>The supplementary Foundations specimen shows actions named by purpose, disabled buttons, errors linked to their fields, selected navigation, captions and forms. Its 36 observations supplement the fixed rubrics without adding points. <strong>{total} foreground/background pairs in the source clear their stated thresholds.</strong> </p><p>The declared palette targets are 5:1 for ordinary text, code text and text for component states. Action text targets 4.5:1, and edges that identify components target 3:1. Litera Reading&#39;s dark selected navigation uses an action pair, so 4.59:1 clears its 4.5:1 target. The source checks list the target for each named role.</p><p>{status} The rendered check uses 4.5:1 as its floor for sampled text. Passing that floor does not mean that every rendered role reaches 5:1.</p><section id="color-repairs"><h3>Three color repairs on 11 November 2026</h3><p>Pulse&#39;s secondary action uses the neutral background and text colors from its theme settings. Litera&#39;s selected navigation uses its named background and text colors. Darkly&#39;s syntax colors with low contrast in light mode use named settings shared across SmallDocs and Quarto. Both modes and renderers are checked in the source repositories; this table reports the SmallDocs specimens used for scoring.</p><div class="table-wrap"><table class="rubric"><caption>Before / after; current component minima include both 1280px and 390px widths.</caption><thead><tr><th>Context</th><th>Role</th><th>10 November</th><th>11 November</th><th>Evidence</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p><strong>Prose leading remains 1.60.</strong> Type sizes, font roles, spacing and shape are unchanged. The color repairs leave the fixed Butterick spacing deduction unchanged. The old component evidence and all previous scores are preserved in the <a href="history/2026-11-10/">10 November archive</a>.</p></section><p>The capture inventory retains unchanged November 10 observations for six project themes. The three repaired themes were recaptured in both modes at both widths on 11 November. <a href="typography-audit/current-screenshots.json">Capture dates and screenshot hashes</a> distinguish these batches. Source checks do not certify every selector, interaction state, device or whole-site accessibility. The new scores use SmallDocs. Checks of the theme settings in Quarto are supplementary.</p><p><a href="typography-audit/foundations-checks.json">All foundation checks</a>  /  <a href="typography-audit/foundations-measurements.json">Raw observations</a></p></section>'''


def source_table():
    pins = json.loads((ROOT.parents[1] / 'theme-sources.json').read_text())
    rows = ''.join(f'<tr><th>{E(p["name"])}</th><td><a href="{p["repository"]}/commit/{p["commit"]}"><code>{p["commit"][:12]}</code></a></td><td><code>{p["foundations_sha256"]}</code></td></tr>' for p in pins if p['name'] in OWNED)
    return '<h3>Current source revisions and file hashes</h3><p>Foundation SHA-256 is the hash of each theme&#39;s foundations.json file.</p><div class="table-wrap"><table class="rubric"><thead><tr><th>Theme</th><th>Commit</th><th>Foundation SHA-256</th></tr></thead><tbody>'+rows+'</tbody></table></div>'


METHOD = '''<section id="method"><h2>Theme specimens and capture method</h2><p>The comparison contains 38 designs. Thirteen have paired light/dark styles. They comprise nine current project themes, three original custom snapshots, and the native Bootstrap baseline. The other 25 are unchanged stock Bootswatches. The collection has 51 theme/mode combinations. Companion modes belong to the project&#39;s Reading adaptations; they are not presented as upstream Bootswatch releases.</p><p>The initial 10 November capture covered all 18 project theme/mode combinations at 1280 × 844 and 390 × 844 CSS pixels. The shared Typography and Code specimens supplied 72 prose/code observations; desktop Controls supplied 18 control observations. Unchanged stock, Bootstrap, and original custom observations are carried forward from October after verifying their assets. The combined score dataset has 204 prose/code and 51 desktop control observations. The separate Foundations specimen adds 36 observations. </p><p>On 11 November, the three repaired themes were recaptured. The batch supplied 24 prose/code, 6 control and 12 foundation observations, plus 42 screenshots. The other six project themes retain their verified November 10 records; unchanged stock/native/original records remain from October. Capture dates are preserved per record.</p><p>Captures use iframes, which embed pages at fixed widths in the same browser. They test how CSS rearranges the page, not physical-device behavior. Each capture waits for fonts to load and the declared CSS color transitions to finish before sampling. Saved current images show the first 650px of each frame; full pages remain in the gallery. The report includes the browser capture code, raw observations, screenshot inventory, source revisions and SHA-256 hashes for checking file contents.</p><h3>Measurement and judgment</h3><ul><li>The two short prose paragraphs are unchanged. Character counts use the positions of rendered characters and exclude the final line of each paragraph. Roughly 490 characters estimate line capacity; a long chapter may move a borderline result.</li><li>Each mode is scored independently. The lower light/dark total becomes the theme score. The new Reading companions therefore expand the tested scope compared with October's native-only Reading modes.</li><li>All typography weights and deduction bands are unchanged. The design rubric and editorial judgment anchors are unchanged. Existing hierarchy, grouping, layout, surface, and personality awards are retained where the new specimens show no material reason to change them; measured color points are recalculated.</li><li>Contrast calculations combine foreground colors and the backgrounds of their containing elements in the sRGB screen color space. Quartz's horizontal gradient is sampled across the reading column. Estimates for component gradients and Vapor's vertical gradient use conservative ranges from the specified gradient colors. These older gradient estimates still need pixel measurements at the sampled locations before relying on borderline contrast results.</li><li>The fixed scores cover sampled normal-state text. The separate foundation checks cover intended source pairs and selected rendered roles; they do not certify every interaction state, icon, syntax class, device, or accessibility criterion.</li><li>The shared specimen does not exercise sidebars, contents panels, marginal notes, or complex Tufte columns. The source repositories are pinned to specific revisions and include separate SmallDocs and Quarto implementations and browser helpers. Their evidence supplements this review and does not supply a new Quarto score.</li><li>The assessment is a self-review using explicit measurements and editorial awards. It is not an independent reader study or endorsement. A high score means close alignment with this short rubric. Treat small differences as ties and inspect flagged components before adopting a theme.</li></ul><p class="caption">Reviewed 10 November; color follow-up 11 November 2026. The October reports, measurements, scores, and screenshots are preserved in <a href="history/2026-10-16/">the review archive</a>. The earlier source snapshot is <code>69c7339</code>; the original custom designs remain at tag <code>before-reading-redesign-2026-10-16</code>. No proprietary PDF or extracts are distributed.</p>'''+source_table()+'</section>'
